  const state = { user: null, permissions: {}, modules: {}, organizationName: '', page: 'dashboard', pageData: null, candidateId: null, appFilters: { q: '', status: 'all', jobId: 'all' }, sidebarOpen: false, roleLabels: {}, userRolesCache: [], permissionRoleKeys: [] };

  const STATUS = { new: { label: 'جدید', cls: 'status-new' }, screening: { label: 'در بررسی', cls: 'status-screening' }, interview: { label: 'مصاحبه', cls: 'status-interview' }, offer: { label: 'پیشنهاد همکاری', cls: 'status-offer' }, hired: { label: 'استخدام‌شده', cls: 'status-hired' }, rejected: { label: 'رد شده', cls: 'status-rejected' }, on_hold: { label: 'در انتظار', cls: 'status-on_hold' } };
